-- ========================================================


function CosPingPong:__init( movePeriod_ )
    if isNull(movePeriod_) then 
        movePeriod_ = 2.0
    end 

    self.isFrom0To1 = true
    self.elapsedTime = 0.0
    self.haldPeriod = movePeriod_ * 0.5 -- 从0到1 的时长
    ---
    self.startVal = 0.0
    self.endVal = 1.0 
    self.currentVal = self.startVal    
end


-- 需手动调用 Delete()
function CosPingPong:__delete()
end

---@return number 
function CosPingPong:SetUpdate()

    -- 计算每帧的时间增量  
    self.elapsedTime = self.elapsedTime + Time.deltaTime

    -- 计算动画进度  
    local progress = self.elapsedTime / self.haldPeriod

    -- 使用缓动函数计算当前进度  
    local easedProgress = CosPingPong._EaseInOutSine(progress)  -- [0f,1f]

    -- 更新目标位置  
    --target.position = Vector3.Lerp(startPosition, endPosition, easedProgress); 
    self.currentVal = Mathf.Lerp( self.startVal, self.endVal, easedProgress ) 

    -- 检查是否需要反转方向  
    if progress >= 1.0  then
    
        self.elapsedTime = 0.0 
        self.isFrom0To1 = not self.isFrom0To1
        -- 交换起始和结束位置  
        local temp = self.startVal
        self.startVal = self.endVal
        self.endVal = temp
    end
    return self.currentVal
end


----------------------------------------------------------


function CosPingPong:SetMovePeriod( movePeriod_ ) 
    if type(movePeriod_)=="number" and movePeriod_ > 0.0 then 
        self.haldPeriod = checkNumber(movePeriod_) * 0.5
        if self.haldPeriod < 0.001 then 
            printError("设置的参数不能太小: "..tostring(movePeriod_))
            self.haldPeriod = 1
        end 
    else 
        printError("参数异常: "..tostring(movePeriod_))
    end 
end



-- ret: [0f,1f]
-- 这么拗口地实现是为了保证在初始阶段, 一定先从 start 移动向 end;
function CosPingPong._EaseInOutSine( t )
    return -(Mathf.Cos(Mathf.PI * t) - 1.0) / 2.0  
end



return CosPingPong
